/** Game/UI short names -> canonical character keys */
const CHARACTER_ALIASES: Record<string, string> = {
  Dan: "Dan Kuso",
  Marucho: "Marucho Marukara",
  Julie: "Julie Makimoto",
  Runo: "Runo Misaki",
  Shun: "Shun Kazami",
  Masquerade: "Masquerade",
  Marduk: "Marduk",
  Kai: "Kai Hokuto",
  Naga: "Naga",
  Joe: "Joe Brown",
};

/** Get the artwork path for a Bakugan, or null when unavailable. */
export function getBakuganImage(name: string): string | null {
  return BAKUGAN_IMAGES[name]?.path ?? null;
}

/** Get the portrait path for a character (accepts short UI names), or null. */
export function getCharacterImage(name: string): string | null {
  const key = CHARACTER_ALIASES[name] ?? name;
  return CHARACTER_IMAGES[key]?.path ?? null;
}
